from abc import ABC, abstractmethod


class Payment(ABC):
    @abstractmethod
    def process(self, amount):
        pass


class CreditCardPayment(Payment):
    def process(self, amount):
        print(f"Processing credit card payment of {amount}")


class PayPalPayment(Payment):
    def process(self, amount):
        print(f"Processing PayPal payment of {amount}")


class CryptoPayment(Payment):
    def process(self, amount):
        print(f"Processing crypto payment of {amount}")


class BankTransferPayment(Payment):
    def process(self, amount):
        print(f"Processing bank transfer of {amount}")


class ApplePayPayment(Payment):
    def process(self, amount):
        print(f"Processing Apple Pay payment of {amount}")


class SimplePaymentFactory:
    @staticmethod
    def create_payment(type_):
        payments = {
            "CREDIT_CARD": CreditCardPayment,
            "PAYPAL": PayPalPayment,
            "CRYPTO": CryptoPayment,
            "BANK_TRANSFER": BankTransferPayment,
            "APPLE_PAY": ApplePayPayment,
        }
        if type_ not in payments:
            raise ValueError(f"Unknown payment type: {type_}")
        return payments[type_]()


if __name__ == "__main__":
    payment = SimplePaymentFactory.create_payment("PAYPAL")
    payment.process("$250")

