#include <bits/stdc++.h>
using namespace std;

class Payment {
public:
    virtual void process(const string& amount) = 0;
    virtual ~Payment() = default;
};

class CreditCardPayment : public Payment {
public:
    void process(const string& amount) override {
        cout << "Processing credit card payment of " << amount << endl;
    }
};

class PayPalPayment : public Payment {
public:
    void process(const string& amount) override {
        cout << "Processing PayPal payment of " << amount << endl;
    }
};

class CryptoPayment : public Payment {
public:
    void process(const string& amount) override {
        cout << "Processing crypto payment of " << amount << endl;
    }
};

class BankTransferPayment : public Payment {
public:
    void process(const string& amount) override {
        cout << "Processing bank transfer of " << amount << endl;
    }
};

class ApplePayPayment : public Payment {
public:
    void process(const string& amount) override {
        cout << "Processing Apple Pay payment of " << amount << endl;
    }
};

class SimplePaymentFactory {
public:
    static unique_ptr<Payment> createPayment(const string& type) {
        if (type == "CREDIT_CARD") return make_unique<CreditCardPayment>();
        if (type == "PAYPAL") return make_unique<PayPalPayment>();
        if (type == "CRYPTO") return make_unique<CryptoPayment>();
        if (type == "BANK_TRANSFER") return make_unique<BankTransferPayment>();
        if (type == "APPLE_PAY") return make_unique<ApplePayPayment>();
        throw invalid_argument("Unknown payment type: " + type);
    }
};

int main() {
    auto payment = SimplePaymentFactory::createPayment("PAYPAL");
    payment->process("$250");
    return 0;
}

