    void prepare() override {
        cout << "Preparing pasta with marinara sauce..." << endl;
        cout << "Adding fresh basil and parmesan..." << endl;
    }

    string getDescription() override { return "Italian Pasta with Marinara"; }
};

class ChineseMeal : public Meal {
