    void prepare() override {
        cout << "Stir frying vegetables and noodles..." << endl;
        cout << "Adding soy sauce and sesame oil..." << endl;
    }

    string getDescription() override { return "Chinese Stir Fry Noodles"; }
};

class MexicanMeal : public Meal {
public:
    void prepare() override {
        cout << "Grilling chicken and warming tortillas..." << endl;
        cout << "Adding salsa, guacamole and cheese..." << endl;
    }

    string getDescription() override { return "Mexican Chicken Tacos"; }
};

