from abc import ABC, abstractmethod


class Meal(ABC):
    @abstractmethod
    def prepare(self):
        pass

    @abstractmethod
    def get_description(self):
        pass


class RestaurantCreator(ABC):
    @abstractmethod
    def create_meal(self):
        pass

    def order_meal(self):
        meal = self.create_meal()
        print(f"Order received: {meal.get_description()}")
        meal.prepare()
        print(f"Meal ready! Enjoy your {meal.get_description()}")
        print()


class JapaneseMeal(Meal):
    def prepare(self):
        print("Preparing sushi rice and slicing fresh fish...")
        print("Rolling maki and plating nigiri...")

    def get_description(self):
        return "Japanese Sushi Platter"


class JapaneseRestaurant(RestaurantCreator):
    def create_meal(self):
        return JapaneseMeal()


if __name__ == "__main__":
    restaurant = JapaneseRestaurant()
