#include <bits/stdc++.h>
using namespace std;

class Meal {
public:
    virtual void prepare() = 0;
    virtual string getDescription() = 0;
    virtual ~Meal() = default;
};

class RestaurantCreator {
public:
    virtual unique_ptr<Meal> createMeal() = 0;

    void orderMeal() {
        auto meal = createMeal();
        cout << "Order received: " << meal->getDescription() << endl;
        meal->prepare();
        cout << "Meal ready! Enjoy your " << meal->getDescription() << endl;
        cout << endl;
    }

    virtual ~RestaurantCreator() = default;
};

class JapaneseMeal : public Meal {
public:
    void prepare() override {
        cout << "Preparing sushi rice and slicing fresh fish..." << endl;
        cout << "Rolling maki and plating nigiri..." << endl;
    }

    string getDescription() override { return "Japanese Sushi Platter"; }
};

class JapaneseRestaurant : public RestaurantCreator {
public:
    unique_ptr<Meal> createMeal() override { return make_unique<JapaneseMeal>(); }
};

int main() {
    unique_ptr<RestaurantCreator> restaurant = make_unique<JapaneseRestaurant>();
    restaurant->orderMeal();
    return 0;
}
